package com.acttub.actingapi.integration.oidc;
import static org.assertj.core.api.Assertions.*; import org.junit.jupiter.api.Test; import org.springframework.boot.test.context.runner.ApplicationContextRunner;
class DevelopmentProviderConfigurationTest {private final ApplicationContextRunner runner=new ApplicationContextRunner().withUserConfiguration(DevelopmentProviderVerifier.class);@Test void onlyOneOrCaseInsensitiveTrueEnablesProvider(){runner.run(c->assertThat(c).doesNotHaveBean(DevelopmentProviderVerifier.class));runner.withPropertyValues("DEVELOPMENT_AUTH_PROVIDER=1").run(c->assertThat(c).hasSingleBean(DevelopmentProviderVerifier.class));runner.withPropertyValues("DEVELOPMENT_AUTH_PROVIDER=TrUe").run(c->assertThat(c).hasSingleBean(DevelopmentProviderVerifier.class));runner.withPropertyValues("DEVELOPMENT_AUTH_PROVIDER=yes").run(c->assertThat(c).doesNotHaveBean(DevelopmentProviderVerifier.class));}@Test void unsupportedProviderIsExplicit(){ProviderRegistry registry=new ProviderRegistry(java.util.List.of());assertThatThrownBy(()->registry.verify("kakao","token")).isInstanceOf(UnsupportedProviderError.class);}}
